def restore_r10b_source(path, source):
    from tools.architecture.test_pp_r00_freeze import git_blob
    lines = source.split("\n")
    for index, current, previous in EDITS[path]:
        if lines[index:index + len(current)] != current:
            raise AssertionError("R10-B inverse anchor changed: " + path)
        lines[index:index + len(current)] = previous
    restored = "\n".join(lines)
    if git_blob(restored.encode("utf-8")) != BEFORE[path]:
        raise AssertionError("R10-B original blob not reconstructed: " + path)
    return restored

class R10bAnomalyNodeEvidenceTest(unittest.TestCase):
    def test_exact_authorized_diff(self):
        from tools.architecture.test_pp_r00_freeze import git_blob
        for path in EDITS:
            source = (ROOT / path).read_text(encoding="utf-8")
            self.assertEqual(AFTER[path], git_blob(source.encode("utf-8")))
            self.assertEqual(BEFORE[path], git_blob(restore_r10b_source(path, source).encode("utf-8")))

    def test_live_read_only_shared_path_and_sealed_evidence(self):
        def read(name):
            return (ROOT / next(path for path in EDITS if path.endswith("/" + name))).read_text(encoding="utf-8")
        root = read("AppCompositionRoot.kt")
        adapter = read("MomoSocialAdapter.kt")
        child = read("MomoPrivateFollowUpController.kt")
        manager = read("RunDiagnosticsManager.kt")
        store = read("RunIncidentEvidenceStore.kt")
        history = read("RunIncidentHistoryStore.kt")
        self.assertIn('channelId = "UNIFIED_ENTRY_PAGE"', root)
        self.assertIn('momoSocialAdapter.captureAnomalyPage(session.taskId, generation, reason)', root)
        self.assertIn('session.lifecycle == com.freedom.core.runtime.PageRuntimeLifecycle.UNCLASSIFIED', root)
        self.assertIn('runCatching { onPageAnomaly(child, reason) }', child)
        self.assertIn('followUpCurrent(child) && (reason.startsWith("UNKNOWN_")', child)
        capture = adapter.split("internal fun captureAnomalyPage(", 1)[1].split("/** Reuse the existing image-browser", 1)[0]
        for token in ("diagnostics.claimPageAnomaly(runId)", "NodeTextCapture.NONE",
                      "snapshot.window != window", "snapshot.windowId != window.windowId",
                      "accessibilityGateway.isWindowCurrent(window)", "diagnostics.activeRunId() != runId"):
            self.assertIn(token, capture)
        self.assertNotIn("gesturePolicy", capture)
        for token in ("event.pageGeneration != window.generation", "event.windowId != window.windowId",
                      "state.pageAnomalyWritePending", "hasQueueRoom(RunEventRollingStore.Lane.WARNING)",
                      "state.incidentStore.recordPageEvidence", "RunIncidentEvidenceStore.files(directory)"):
            self.assertIn(token, manager)
        for token in ("MAX_PAGE_EVIDENCE = 16", "MAX_PAGE_EVIDENCE_BYTES = 128L * 1024L",
                      "includeText = false", "signature in pageSignatures", "writeAtomic(file, payload)",
                      "+ pageEvidenceFiles(runDirectory)"):
            self.assertIn(token, store)
        self.assertIn("RunIncidentEvidenceStore.pageEvidenceFiles(run).isEmpty()", history)
        self.assertIn("sourceFiles = RunIncidentEvidenceStore.files(run)", history)

    def test_inverse_rejects_disabled_privacy_window_and_capacity_guards(self):
        for name, old, new in (
            ("MomoSocialAdapter.kt", "snapshot.window != window", "false"),
            ("RunDiagnosticsManager.kt", "event.pageGeneration != window.generation", "false"),
            ("RunIncidentEvidenceStore.kt", "includeText = false, indent", "includeText = true, indent"),
            ("RunIncidentEvidenceStore.kt", "MAX_PAGE_EVIDENCE = 16", "MAX_PAGE_EVIDENCE = 160"),
        ):
            path = next(path for path in EDITS if path.endswith("/" + name))
            source = (ROOT / path).read_text(encoding="utf-8")
            self.assertIn(old, source)
            with self.subTest(path=path, token=old), self.assertRaises(AssertionError):
                restore_r10b_source(path, source.replace(old, new, 1))
